package com.brazilsoccer.mcp;
import java.io.*;import java.nio.file.*;import java.time.*;import java.util.*;

/** MCP 2024-11-05 compatible stdio server. Start with Main; every stdout line is JSON-RPC. */
public final class McpServer {
  private final SoccerService service; public McpServer(SoccerService service){this.service=service;}
  @SuppressWarnings("unchecked") public void serve(InputStream in,PrintStream out)throws IOException {try(var r=new BufferedReader(new InputStreamReader(in))){for(String line;(line=r.readLine())!=null;){if(line.isBlank())continue;try{Map<String,Object>q=(Map<String,Object>)Json.parse(line);Object id=q.get("id");String method=String.valueOf(q.get("method"));Map<String,Object>p=q.get("params") instanceof Map<?,?> x?(Map<String,Object>)x:Map.of();Object result=handle(method,p);if(id!=null)out.println(Json.write(Map.of("jsonrpc","2.0","id",id,"result",result)));}catch(Exception e){out.println(Json.write(Map.of("jsonrpc","2.0","id",null,"error",Map.of("code",-32602,"message",e.getMessage()==null?"Invalid request":e.getMessage()))));}}}}
  private Object handle(String method,Map<String,Object> p){return switch(method){case "initialize"->Map.of("protocolVersion","2024-11-05","capabilities",Map.of("tools",Map.of()),"serverInfo",Map.of("name","brazilian-soccer","version","1.0.0"));case "notifications/initialized"->Map.of();case "tools/list"->Map.of("tools",tools());case "tools/call"->call(str(p,"name"),map(p,"arguments"));case "ping"->Map.of();default->throw new IllegalArgumentException("Unknown method: "+method);};}
  private List<Map<String,Object>> tools(){return List.of(tool("search_matches","Search all five match datasets by team, opponent, competition, season, or date range."),tool("team_statistics","Calculate wins, draws, losses, goals and win rate."),tool("head_to_head","Compare two teams across loaded matches."),tool("standings","Calculate a season table from match results."),tool("search_players","Find FIFA players by name, nationality, club, or position."),tool("biggest_wins","List matches with the largest score margins."),tool("ask","Handle common English or Portuguese soccer questions."));}
  private static Map<String,Object> tool(String n,String d){return Map.of("name",n,"description",d,"inputSchema",Map.of("type","object","additionalProperties",true));}
  private Object call(String name,Map<String,Object>a){Object data=switch(name){case "search_matches"->service.findMatches(str(a,"team"),str(a,"opponent"),str(a,"competition"),str(a,"season"),date(str(a,"from")),date(str(a,"to")),integer(a,"limit",50));case "team_statistics"->service.teamStats(str(a,"team"),str(a,"season"),str(a,"competition"),bool(a,"home_only"));case "head_to_head"->service.headToHead(required(a,"first_team"),required(a,"second_team"),str(a,"season"),str(a,"competition"));case "standings"->service.standings(required(a,"season"),str(a,"competition").isBlank()?"Brasileirão":str(a,"competition"));case "search_players"->service.findPlayers(str(a,"name"),str(a,"nationality"),str(a,"club"),str(a,"position"),integer(a,"limit",50));case "biggest_wins"->service.biggestWins(str(a,"competition"),integer(a,"limit",20));case "ask"->ask(required(a,"question"));default->throw new IllegalArgumentException("Unknown tool: "+name);};String summary=data instanceof Collection<?> c?c.size()+" result(s)":String.valueOf(data);return Map.of("content",List.of(Map.of("type","text","text",summary)),"structuredContent",data);}
  private Object ask(String q){String n=TeamNames.normalize(q);String year=java.util.regex.Pattern.compile("\\b(19|20)\\d{2}\\b").matcher(q).results().map(x->x.group()).findFirst().orElse("");if(n.contains("top")&&n.contains("player")||n.contains("jogador"))return service.findPlayers("",n.contains("brazil")?"Brazil":"","","",20);if(n.contains("standing")||n.contains("tabela")||n.contains("who won"))return service.standings(year,"Brasileirão");return service.findMatches(extractTeam(q),"","",year,null,null,50);}
  private static String extractTeam(String q){String x=q.replaceAll("(?i)when did|what matches did|show me|find|last play|played|em |em "," ").replaceAll("(?i)\\b(19|20)\\d{2}\\b","").trim();return x;}
  private static String str(Map<String,Object>m,String k){Object x=m.get(k);return x==null?"":String.valueOf(x);}private static String required(Map<String,Object>m,String k){String x=str(m,k);if(x.isBlank())throw new IllegalArgumentException(k+" is required");return x;}@SuppressWarnings("unchecked")private static Map<String,Object>map(Map<String,Object>m,String k){return m.get(k) instanceof Map<?,?>x?(Map<String,Object>)x:Map.of();}private static int integer(Map<String,Object>m,String k,int d){try{return m.containsKey(k)?((Number)m.get(k)).intValue():d;}catch(Exception e){return d;}}private static boolean bool(Map<String,Object>m,String k){return Boolean.TRUE.equals(m.get(k));}private static LocalDate date(String s){return s.isBlank()?null:SoccerRepository.parseDate(s);}
}
